function divide(a, b) {
  if (typeof a !== "number") throw new TypeError("a must be number");
  if (b === 0) throw new RangeError("division by zero");
  return a / b;
}

try {
  divide("1", 2);
} catch (err) {
  console.log(err.name, err.message); // TypeError ...
  console.log(err.stack);
}

class HttpError extends Error {
  constructor(status, message, options) {
    super(message, options);
    this.name = "HttpError";
    this.status = status;
  }
}

async function fetchUser(id) {
  const res = await fetch(`/api/users/${id}`);
  if (res.status === 404) throw new HttpError(404, `user ${id} not found`);
  if (!res.ok) throw new HttpError(res.status, await res.text());
  return res.json();
}

async function loadConfig(path) {
  try {
    return JSON.parse(await readFile(path));
  } catch (err) {
    throw new Error(`Failed to load ${path}`, { cause: err });
  }
}

try {
  await loadConfig("/etc/app.json");
} catch (err) {
  console.log(err.message);
  console.log(err.cause); // original SyntaxError or ENOENT
}
